item(id='salary-sheet-slip-excel', kit='office-hr', kind='excel', icon='💰', name='Salary Sheet & Payslip (Excel)',
     title='Salary Sheet with Payslip in Excel: PF, ESI, Net Pay and Salary Slip Format',
     desc='Free Excel salary sheet for small offices: earned salary by days paid, PF and ESI deductions, professional tax, TDS, advance and net pay, plus a printable salary slip.',
     files=[('Salary-Sheet-and-Payslip.xlsx', 'Salary sheet and payslip workbook')],
     lead='Monthly payroll for a small team in one workbook. List your employees and their monthly salary once; each month type the days paid and any deductions. The sheet works out earned salary, employee PF and ESI, net pay and employer contributions, and the Payslip sheet prints a salary slip for any employee with the net pay in words.',
     inside=['Setup: company, month, working days, PF and ESI on/off', 'Employees: code, name, designation, department, joining date, PAN, UAN, bank account, basic, HRA and other allowances',
             'Salary sheet: days paid, earned salary, PF (12% of basic up to the ₹15,000 wage ceiling), ESI (0.75% when gross is up to ₹21,000), professional tax, TDS, advance, net pay',
             'Employer PF and ESI shown separately for cost', 'Payslip sheet: pick an employee code, print on A4 with net pay in words'],
     steps=['On the Setup sheet type the company name, the month (first day) and the working days, and choose whether PF and ESI apply to you.',
            'On the Employees sheet list each employee with their monthly basic, HRA and other allowances.',
            'Each month, on the Salary sheet type the days paid for each employee and any professional tax, TDS and advance to deduct.',
            'Check the net pay column. Totals at the bottom give the month\'s salary bill.', 'On the Payslip sheet pick an employee code and print. Repeat for each employee.',
            'Save a copy of the file for each month.'],
     tips=['Professional tax depends on your state and salary slab; type it per employee.', 'PF and ESI rules and limits change from time to time; confirm the current rates with your consultant or the EPFO/ESIC websites.',
           'Days paid can be a decimal (for example 25.5) for half days.'],
     faqs=[('How is PF calculated here?', '12 percent of earned basic salary, limited to a basic of ₹15,000 (so at most ₹1,800), which is the usual practice. If your company pays PF on full basic, ask for a change via the contact page.'),
           ('When is ESI deducted?', 'When ESI is turned on and the employee\'s earned gross salary for the month is ₹21,000 or less: 0.75 percent from the employee and 3.25 percent from the employer.'),
           ('Is TDS calculated?', 'No. Income tax depends on the employee\'s regime, investments and annual income; type the monthly TDS amount you have worked out.')])

